-- ============================================================
-- WBH Product Catalog — Full Migration with Images
-- Run this in your Supabase SQL Editor
-- Replaces old PRD-xxx products with new PROD-xxx products
-- ============================================================

-- Step 1: Add image columns if they don't exist
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS image_url_2 TEXT;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS image_url_3 TEXT;

-- Step 2: Delete old seed data (PRD-xxx IDs)
DELETE FROM public.recommendation_items WHERE product_id LIKE 'PRD-%';
DELETE FROM public.products WHERE id LIKE 'PRD-%';

-- Step 3: Insert all updated products
-- ==========================================
-- Cleansers (CAT-06)
-- ==========================================
ON CONFLICT (id) DO UPDATE SET
  category_id = EXCLUDED.category_id, category_name = EXCLUDED.category_name,
  product_name = EXCLUDED.product_name, brand = EXCLUDED.brand, sub_type = EXCLUDED.sub_type,
  finish = EXCLUDED.finish, best_for = EXCLUDED.best_for, confidence_level = EXCLUDED.confidence_level,
  skin_concern_tags = EXCLUDED.skin_concern_tags, image_url = EXCLUDED.image_url,
  image_url_2 = EXCLUDED.image_url_2, image_url_3 = EXCLUDED.image_url_3;

