-- Step 4: Update category product counts
UPDATE public.categories c SET product_count = (
  SELECT COUNT(*) FROM public.products p WHERE p.category_id = c.id
);

-- Step 5: Verify
SELECT category_name, COUNT(*) as total FROM public.products GROUP BY category_name ORDER BY total DESC;
